    public static unsafe sg_shader_desc physics_demo_smooth_shader_desc(sg_backend backend) {
        if (backend == SG_BACKEND_METAL_MACOS) {
            sg_shader_desc desc = default(sg_shader_desc);
            desc.vertex_func.source = System.Text.Encoding.UTF8.GetString(vs_smooth_source_metal_macos);
            desc.vertex_func.entry = "main0";
            desc.fragment_func.source = System.Text.Encoding.UTF8.GetString(fs_smooth_source_metal_macos);
            desc.fragment_func.entry = "main0";
            desc.attrs[0].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.attrs[1].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.attrs[2].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.attrs[3].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.attrs[4].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.attrs[5].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.attrs[6].base_type = SG_SHADERATTRBASETYPE_FLOAT;
            desc.uniform_blocks[0].stage = SG_SHADERSTAGE_VERTEX;
            desc.uniform_blocks[0].layout = SG_UNIFORMLAYOUT_STD140;
            desc.uniform_blocks[0].size = 64;
            desc.uniform_blocks[0].msl_buffer_n = 0;
            desc.uniform_blocks[1].stage = SG_SHADERSTAGE_FRAGMENT;
            desc.uniform_blocks[1].layout = SG_UNIFORMLAYOUT_STD140;
            desc.uniform_blocks[1].size = 32;
            desc.uniform_blocks[1].msl_buffer_n = 1;
            desc.label = "physics_demo_smooth_shader";
            return desc;
        }
        return default(sg_shader_desc);
